#include <stddef.h>
struct node { int val; struct node *next; };
struct node *find(struct node *head, int v) {
    while (head != NULL && head->val != v)
        head = head->next;
    return head;
}
int value_of(struct node *list, int v) {
    struct node *n = find(list, v);
    return n->val;
}

